describe('Animated Transitions Between Async Page Loads', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display animated transition when navigating between async pages', () => {
    // Intercept the async API call for page navigation
    cy.intercept('GET', '/api/page-data').as('pageData');

    // Click the navigation button to trigger async page load
    cy.get('[data-testid="nav-to-settings"]').click();

    // Wait for the API call to complete
    cy.wait('@pageData');

    // Verify the animated transition element appears
    cy.get('[data-testid="transition-spinner"]').should('be.visible');
    cy.get('[data-testid="transition-spinner"]').should('have.class', 'animate-fade-in');

    // Verify the new page content is visible after transition
    cy.get('[data-testid="settings-page-title"]').should('be.visible');
    cy.get('[data-testid="settings-page-title"]').should('contain', 'Settings');

    // Verify the transition animation completes
    cy.get('[data-testid="transition-spinner"]').should('not.exist');
    cy.get('[data-testid="settings-page-content"]').should('be.visible');
  });

  it('should handle transition animation when async page load fails', () => {
    // Intercept the async API call and force it to fail
    cy.intercept('GET', '/api/page-data', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('pageDataError');

    // Click the navigation button
    cy.get('[data-testid="nav-to-profile"]').click();

    // Wait for the failed API call
    cy.wait('@pageDataError');

    // Verify error state is displayed with animation
    cy.get('[data-testid="transition-error-message"]').should('be.visible');
    cy.get('[data-testid="transition-error-message"]').should('have.class', 'animate-shake');
    cy.get('[data-testid="transition-error-message"]').should('contain', 'Failed to load');

    // Verify the original page content is still visible
    cy.get('[data-testid="dashboard-page-title"]').should('be.visible');
    cy.get('[data-testid="dashboard-page-title"]').should('contain', 'Dashboard');

    // Verify error recovery button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry');
  });
});
